<script setup>
import{computed}from'vue';import{ArrowUpRight,RefreshCw,BrainCircuit}from'lucide-vue-next';import{useAppStore}from'../stores/app';import GameCard from'../components/game/GameCard.vue';import TeamLogo from'../components/team/TeamLogo.vue';import LoadingState from'../components/ui/LoadingState.vue';import EmptyState from'../components/ui/EmptyState.vue'
const store=useAppStore(),data=computed(()=>store.dashboard),featured=computed(()=>data.value?.featured),dateLabel=computed(()=>new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'America/New_York'}).format(new Date(featured.value?.gameTime||Date.now())))
const percent=value=>value==null?'Pending':`${(Number(value)*100).toFixed(1)}%`
</script>
<template><div v-if="data" class="home"><section class="hero"><div class="hero-main"><span class="eyebrow">{{dateLabel}} / THE DAILY READ</span><h1>Baseball,<br><i>before first pitch.</i></h1><p>One place for the games, people, form, and live circumstances that shape every matchup.</p><div class="actions"><RouterLink to="/schedule">OPEN TODAY’S GAMES <ArrowUpRight :size="15"/></RouterLink><button @click="store.load(true)"><RefreshCw :size="14"/>{{store.loading?'SYNCING':'REFRESH'}}</button></div></div><div class="daily-card"><header><span><BrainCircuit :size="16"/> MODEL BRIEF</span><small>TOP MATCHUP / LIVE + NEXT 7 DAYS</small></header><template v-if="featured"><div class="brief-match"><div><TeamLogo :team="featured.away" :size="52"/><b>{{featured.away.abbr}}</b><small>{{featured.away.record||'—'}}</small></div><span><small>{{featured.status}}</small><strong class="mono">{{featured.time}}</strong><em>{{featured.stadium}}</em></span><div><TeamLogo :team="featured.home" :size="52"/><b>{{featured.home.abbr}}</b><small>{{featured.home.record||'—'}}</small></div></div><div class="brief-signals"><span><small>MATCHUP QUALITY</small><b>{{featured.brief?.combinedStandingLabel||'Pending'}}</b></span><span><small>MODEL LEAN</small><b>{{featured.brief?.modelTeam?.abbr||'Pending'}}<template v-if="featured.brief?.modelProbability"> · {{percent(featured.brief.modelProbability)}}</template></b></span></div><RouterLink :to="`/games/${featured.id}`">READ THE MATCHUP <ArrowUpRight :size="14"/></RouterLink></template><div v-else class="brief-empty"><span>NO UPCOMING MATCHUP</span><p>No live or scheduled MLB game was found in the next seven days.</p></div></div></section><section class="pulse"><div v-for="metric in data.metrics" :key="metric.label"><span>{{metric.label}}</span><strong class="mono">{{metric.value}}</strong><small>{{metric.delta}}</small></div></section><section class="split"><div class="games"><header class="section-head"><div><span class="eyebrow">THE BOARD</span><h2>Today’s games</h2></div><RouterLink to="/schedule">FULL SCHEDULE <ArrowUpRight :size="13"/></RouterLink></header><div v-if="data.live.length" class="game-list"><GameCard v-for="game in data.live" :key="game.id" :game="game" live/></div><div v-if="data.today.length" class="game-list"><GameCard v-for="game in data.today.slice(0,4)" :key="game.id" :game="game"/></div><EmptyState v-if="!data.live.length&&!data.today.length" kind="games" eyebrow="TODAY’S SLATE" title="No MLB games today" detail="The official schedule returned no live or upcoming games for today. The model brief above looks ahead for the next strongest matchup." action-label="Browse the schedule" action-to="/schedule"/></div><aside><header class="section-head"><div><span class="eyebrow">TABLE</span><h2>Best records</h2></div></header><template v-if="data.standings.length"><RouterLink v-for="(team,index) in data.standings" :key="team.id" :to="`/teams/${team.id}`" class="standing"><span class="mono">{{String(index+1).padStart(2,'0')}}</span><TeamLogo :team="team" :size="34"/><div><b>{{team.name}}</b><small>{{team.wins}}–{{team.losses}} · {{team.streak||'—'}}</small></div><strong class="mono">{{team.pct}}</strong></RouterLink><RouterLink to="/teams" class="all-teams">BROWSE ALL 30 CLUBS <ArrowUpRight :size="13"/></RouterLink></template><EmptyState v-else kind="teams" title="No standings found" detail="Official team records are not available yet."/></aside></section><footer class="source-line"><span><i></i> MLB STATSAPI</span><span><i></i> OPEN-METEO</span><span><i></i> NINTH MODEL</span><p>Real provider data. Missing inputs remain pending.</p></footer></div><LoadingState v-else label="Building today’s read" detail="Loading the official slate, standings, weather and model brief."/></template>
<style scoped>.home{display:grid;gap:0}.hero{min-height:500px;display:grid;grid-template-columns:1.35fr .65fr;gap:45px;align-items:center;padding:55px 0;border-bottom:1px solid var(--line)}h1{font-size:clamp(58px,8vw,116px);line-height:.82;letter-spacing:-.09em;margin:19px 0 30px;max-width:900px}h1 i{font-style:normal;color:var(--orange)}.hero-main>p{max-width:600px;font-size:15px;line-height:1.7;color:var(--muted)}.actions{display:flex;gap:8px;margin-top:27px}.actions a,.actions button{display:flex;align-items:center;gap:8px;padding:13px 15px;border:1px solid var(--ink);font:600 9px 'DM Mono';text-decoration:none;background:transparent;cursor:pointer}.actions a{background:var(--ink);color:var(--paper)}.daily-card{background:var(--contrast);color:var(--on-contrast);padding:21px;min-height:310px;display:flex;flex-direction:column}.daily-card header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #363a34;padding-bottom:13px}.daily-card header span{display:flex;gap:8px;align-items:center;font:600 9px 'DM Mono';color:var(--accent)}.daily-card header small{font:7px 'DM Mono';color:#aeb4aa}.brief-match{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;text-align:center;gap:8px;margin:34px 0}.brief-match>div,.brief-match>span{display:flex;align-items:center;flex-direction:column;gap:6px}.brief-match b{font:500 18px 'DM Mono'}.brief-match small,.brief-match em{font:7px 'DM Mono';color:#aeb4aa;font-style:normal}.brief-match strong{font-size:12px;color:var(--accent)}.brief-weather{display:flex;justify-content:space-between;border-top:1px solid #363a34;padding:13px 0}.brief-weather span{font:7px 'DM Mono';color:#aeb4aa}.brief-weather b{font:500 9px 'DM Mono'}.daily-card>a{display:flex;justify-content:space-between;align-items:center;margin-top:auto;padding-top:14px;border-top:1px solid #363a34;text-decoration:none;font:600 8px 'DM Mono';color:var(--accent)}.pulse{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}.pulse>div{padding:23px 18px;border-right:1px solid var(--line);display:grid}.pulse>div:first-child{padding-left:0}.pulse>div:last-child{border:0}.pulse span{font:500 8px 'DM Mono';color:var(--muted);text-transform:uppercase}.pulse strong{font-size:32px;letter-spacing:-.07em;margin:10px 0 5px}.pulse small{font:7px 'DM Mono';color:var(--muted)}.split{display:grid;grid-template-columns:1fr 330px;gap:35px;padding:45px 0}.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:17px}.section-head h2{font-size:28px;letter-spacing:-.055em;margin:6px 0 0}.section-head>a{display:flex;align-items:center;gap:6px;font:600 8px 'DM Mono';text-decoration:none}.game-list{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-bottom:9px}.no-games{padding:40px;border:1px solid var(--line);color:var(--muted);font-size:11px;text-align:center}.standing{display:grid;grid-template-columns:22px 36px 1fr auto;align-items:center;gap:8px;padding:11px 0;border-top:1px solid var(--line);text-decoration:none}.standing>span{font-size:7px;color:var(--muted)}.standing>div{display:flex;flex-direction:column}.standing b{font-size:10px}.standing small{font-size:7px;color:var(--muted);margin-top:3px}.standing strong{font-size:9px}.all-teams{display:flex;justify-content:space-between;align-items:center;margin-top:12px;padding:13px;background:var(--accent);text-decoration:none;font:600 8px 'DM Mono'}.source-line{display:flex;gap:20px;align-items:center;border-top:1px solid var(--line);padding:18px 0;font:500 7px 'DM Mono';color:var(--muted)}.source-line span i{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--green);margin-right:5px}.source-line p{margin-left:auto}.load{padding:90px;text-align:center;font:9px 'DM Mono'}@media(max-width:980px){.hero{grid-template-columns:1fr;min-height:auto}.daily-card{max-width:600px}.split{grid-template-columns:1fr}.split aside{max-width:600px}.pulse{grid-template-columns:repeat(2,1fr)}.pulse>div:nth-child(2){border-right:0}}@media(max-width:680px){.hero{padding:36px 0;gap:25px}h1{font-size:58px}.game-list{grid-template-columns:1fr}.pulse>div{padding:16px 10px}.pulse>div:first-child{padding-left:0}.pulse strong{font-size:25px}.split{padding:30px 0}.source-line{flex-wrap:wrap}.source-line p{width:100%;margin:0}}</style>
